VALUES
  ('ROLE-LEARNER', 'learner', 'Learner', 'Undergraduate & Graduate Student Cohort', 'Submits academic and support requests, queries policy-grounded answers, and provides resolution feedback.', ARRAY['submit_academic_petition']::text[], FALSE, FALSE, FALSE, '2025-08-01', NULL, '2026-09-01T13:30:00+05:30'),
  ('ROLE-INSTRUCTOR', 'instructor', 'Instructor', 'Faculty & Course Instructional Staff', 'Submits course-related requests, attests to student petitions, and proposes policy revisions.', ARRAY['submit_faculty_course_request', 'propose_policy_revision']::text[], FALSE, FALSE, FALSE, '2025-08-01', NULL, '2026-09-01T13:30:00+05:30'),
