  ('ROLE-ACADEMIC_ADMINISTRATOR', 'academic_administrator', 'Academic Administrator', 'Deans, Registrars & Appeals Review Boards', 'Adjudicates escalated petitions, reviews policy compliance, publishes knowledge articles, and oversees SLAs.', ARRAY['initiate_administrative_review', 'approve_policy_escalation', 'publish_knowledge_article', 'configure_department_routing']::text[], TRUE, TRUE, TRUE, '2025-08-01', NULL, '2026-09-01T13:30:00+05:30'),
  ('ROLE-PLATFORM_ADMINISTRATOR', 'platform_administrator', 'Platform Administrator', 'Enterprise IT & Platform Governance Authority', 'Configures cross-institutional settings, manages authentication providers, and reviews system integrity metrics.', ARRAY['initiate_administrative_review', 'publish_knowledge_article', 'configure_department_routing', 'configure_platform_governance']::text[], TRUE, TRUE, TRUE, '2025-08-01', NULL, '2026-09-01T13:30:00+05:30')
