  ('CAT-FINAID', 'Financial Aid', 'FINAID', 'Office of Financial Aid & Scholarships', 'Office of Financial Aid & Scholarships', 'Financial Aid Appeals & Compliance Review Committee', 'Financial Aid Appeals & Compliance Review Committee', 'RULE-FINAID-001', 'support_staff', 'academic_administrator', 'Routes Financial Aid disbursement, SAP appeal, scholarship eligibility, and emergency aid inquiries to the Office of Financial Aid & Scholarships; escalates appeals and policy exceptions to the Financial Aid Appeals & Compliance Review Committee.', ARRAY['academic', 'financial aid']::text[], TRUE, '2026-01-01T00:00:00+05:30', NULL, '2026-09-01T13:30:00+05:30'),
