  ('CAT-ACCESS', 'Accessibility', 'ACCESS', 'Disability & Accessibility Services Office', 'Disability & Accessibility Services Office', 'ADA / Section 504 Compliance Review Panel', 'ADA / Section 504 Compliance Review Panel', 'RULE-ACCESS-001', 'support_staff', 'academic_administrator', 'Routes exam accommodation letters, assistive technology requests, captioning, and physical classroom access adjustments to the Disability & Accessibility Services Office; escalates accommodation disputes or urgent compliance barriers to the ADA / Section 504 Compliance Review Panel.', ARRAY['academic', 'accessibility']::text[], TRUE, '2026-01-01T00:00:00+05:30', NULL, '2026-09-01T13:30:00+05:30')
