INSERT INTO public.policy_documents (policy_id, domain, category_id, title, version, effective_date, expiration_date, lifecycle_state, supersedes_policy_id, superseded_by_policy_id, summary, content, authoritative_section_ref, source_name, source_url, dataset_or_doc_version, retrieval_date, license_terms, attribution, transformations_performed, discarded_fields, is_synthetic_policy, published_by_profile_id, created_at, updated_at)
VALUES
  ('POL-FINAID-2026-001', 'FINAID', 'CAT-FINAID', 'Satisfactory Academic Progress (SAP) & Financial Aid Appeal Policy (Legacy)', '1.0', '2025-01-01', '2026-06-30', 'expired', NULL, 'POL-FINAID-2026-002', '[SYNTHETIC DEMONSTRATION POLICY — EXPIRED] Legacy SAP appeal deadline rules effective through June 30, 2026.', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-06-30), students placed on financial aid suspension had 10 calendar days from term start to submit a Satisfactory Academic Progress (SAP) appeal with supporting documentation to the Office of Financial Aid & Scholarships.', 'Section 4.1 (Superseded)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-finaid-2026-001', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2025-01-01T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-FINAID-2026-002', 'FINAID', 'CAT-FINAID', 'Satisfactory Academic Progress (SAP) & Financial Aid Appeal Policy', '2.0', '2026-07-01', NULL, 'active', 'POL-FINAID-2026-001', NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Current SAP appeal requirements, 15-business-day submission window, and committee escalation rules.', '[SYNTHETIC DEMONSTRATION POLICY] Effective July 1, 2026 (Version 2.0, superseding POL-FINAID-2026-001 v1.0), students whose cumulative GPA falls below 2.0 or pace of completion falls below 67% may submit a written Satisfactory Academic Progress (SAP) appeal within 15 business days of notification. Standard eligibility verifications are handled by the Office of Financial Aid & Scholarships; second-level SAP appeals and emergency statutory waivers must be escalated to the Financial Aid Appeals & Compliance Review Committee.', 'Section 4.2 (Current)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-finaid-2026-002', '2026.10-seed-20261022-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-07-01T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-FINAID-2026-003', 'FINAID', 'CAT-FINAID', 'Term Aid Disbursement & Census Date Proration Policy', '1.0', '2026-01-15', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Rules governing grant/scholarship disbursement timing and enrollment intensity proration at census date.', '[SYNTHETIC DEMONSTRATION POLICY] Institutional grants and federal aid disburse no earlier than 10 days prior to the official term start date, contingent upon active enrollment in at least 6 credit hours for half-time status or 12 credit hours for full-time status locked at the add/drop census deadline.', 'Section 2.3', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-finaid-2026-003', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-15T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-FINAID-2026-004', 'FINAID', 'CAT-FINAID', 'Emergency Hardship Relief Grants & Statutory Aid Waiver Regulations', '1.0', '2026-02-01', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Emergency micro-grants for sudden hardship and statutory tuition waivers.', '[SYNTHETIC DEMONSTRATION POLICY] Students experiencing acute financial disruption may petition for emergency grant disbursements of up to $2,500. Note: Section 5.1 permits emergency disbursements within 48 business hours of verification, representing a priority exception to standard census proration rules under POL-FINAID-2026-003.', 'Section 5.1 (Conflicting Provision)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-finaid-2026-004', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-02-01T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-FINAID-2026-005', 'FINAID', 'CAT-FINAID', 'Institutional Merit Scholarship Retention & Renewal Standards', '1.0', '2026-01-15', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Merit scholarship renewal GPA thresholds, continuous enrollment requirements, and probation grace periods.', '[SYNTHETIC DEMONSTRATION POLICY] Institutional merit scholarships require a minimum cumulative GPA of 3.20 evaluated at the end of each spring semester. Learners failing the threshold receive one probationary grace semester before award cancellation.', 'Section 3.4', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-finaid-2026-005', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-15T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-FINAID-2026-006', 'FINAID', 'CAT-FINAID', 'International Student Financial Aid & Campus Employment Regulations', '1.0', '2026-01-15', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Restrictions and institutional fellowship disbursements for F-1 / J-1 visa holders.', '[SYNTHETIC DEMONSTRATION POLICY] International students holding F-1/J-1 visas may receive departmental fellowships and emergency campus employment awards up to 20 hours per week during academic terms, subject to International Student Center immigration verification.', 'Section 6.2', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-finaid-2026-006', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-15T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-REG-2026-001', 'REG', 'CAT-REG', 'Course Add/Drop & Late Withdrawal Petition Policy (Legacy)', '1.0', '2025-01-01', '2026-05-31', 'expired', NULL, 'POL-REG-2026-002', '[SYNTHETIC DEMONSTRATION POLICY — EXPIRED] Legacy course drop and withdrawal rules effective through May 31, 2026.', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-05-31), students could drop courses without a W grade through Week 3 of the semester.', 'Section 3.1 (Superseded)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-reg-2026-001', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2025-01-01T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-REG-2026-002', 'REG', 'CAT-REG', 'Course Add/Drop & Late Withdrawal Petition Policy', '2.0', '2026-06-01', NULL, 'active', 'POL-REG-2026-001', NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Current 10-business-day add/drop window, W-grade withdrawal deadline, and retroactive petition escalation.', '[SYNTHETIC DEMONSTRATION POLICY] Effective June 1, 2026 (Version 2.0, superseding POL-REG-2026-001 v1.0), standard course additions and drops without transcript notation must be completed within the first 10 business days of the term via the Office of the University Registrar. Course withdrawals with a W notation are permitted through the end of Week 8. Any retroactive withdrawal or late drop petition after Week 8 requires documented extenuating circumstances and mandatory escalation to the Academic Senate Registration Review Board.', 'Section 3.2 (Current)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-reg-2026-002', '2026.10-seed-20261022-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-06-01T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-REG-2026-003', 'REG', 'CAT-REG', 'Credit Overload & Cross-Departmental Prerequisite Override Policy', '1.0', '2026-01-10', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Maximum term credit cap (18 credits) and approval rules for 19–22 credit overload petitions.', '[SYNTHETIC DEMONSTRATION POLICY] Standard undergraduate enrollment is capped at 18 credit hours per regular term. Requests to enroll in 19 to 22 credit hours require a minimum cumulative GPA of 3.30 and advisor attestation processed by the Office of the University Registrar.', 'Section 5.4', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-reg-2026-003', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-10T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-REG-2026-004', 'REG', 'CAT-REG', 'Grade Forgiveness & Course Repetition Regulations', '1.0', '2026-01-10', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Maximum course repeat allowances and grade replacement computation rules.', '[SYNTHETIC DEMONSTRATION POLICY] Undergraduate students may repeat up to 3 courses (maximum 12 credit hours) for grade replacement. The second earned grade replaces the initial grade in cumulative GPA computation, though all attempts remain permanently visible on transcript.', 'Section 4.3', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-reg-2026-004', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-10T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-REG-2026-005', 'REG', 'CAT-REG', 'Independent Study, Cross-Registration & Dean Approval Workflows', '1.0', '2026-01-10', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Requirements for variable credit independent study and consortium cross-registration.', '[SYNTHETIC DEMONSTRATION POLICY] Enrolling in independent study courses requires a structured syllabus, supervising faculty signature, and department chair approval filed with the Registrar no later than the add/drop census date.', 'Section 7.1', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-reg-2026-005', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-10T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-REG-2026-006', 'REG', 'CAT-REG', 'Academic Standing, Probation & Reinstatement Appeals', '1.0', '2026-01-10', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Good standing thresholds, academic probation triggers, and suspension appeal criteria.', '[SYNTHETIC DEMONSTRATION POLICY] Undergraduates with cumulative GPA below 2.00 are placed on academic probation. Two consecutive probationary terms trigger academic suspension, which may be appealed within 10 business days to the Dean of Academic Affairs.', 'Section 8.2', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-reg-2026-006', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-10T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-IT-2026-001', 'IT', 'CAT-IT', 'Institutional Identity, SSO & Multi-Factor Authentication Policy (Legacy)', '1.0', '2025-01-01', '2026-04-30', 'expired', NULL, 'POL-IT-2026-002', '[SYNTHETIC DEMONSTRATION POLICY — EXPIRED] Legacy SMS-based two-factor reset rules expired April 30, 2026.', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-04-30), SMS text codes were permitted as a primary multi-factor authentication method for institutional accounts.', 'Section 1.1 (Superseded)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-it-2026-001', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2025-01-01T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-IT-2026-002', 'IT', 'CAT-IT', 'Institutional Identity, SSO & Multi-Factor Authentication Policy', '2.0', '2026-05-01', NULL, 'active', 'POL-IT-2026-001', NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Current hardware token / authenticator app MFA requirement and identity verification procedures.', '[SYNTHETIC DEMONSTRATION POLICY] Effective May 1, 2026 (Version 2.0, superseding POL-IT-2026-001 v1.0), all learners, instructors, and staff must use FIDO2 passkeys or TOTP authenticator apps for Single Sign-On (SSO). Routine MFA device resets are handled by the Campus IT Operations & Identity Desk after photo-ID verification. Suspected account compromise or privilege anomalies must be escalated immediately to the Information Security & Infrastructure Escalation Unit.', 'Section 1.2 (Current)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-it-2026-002', '2026.10-seed-20261022-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-05-01T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-IT-2026-003', 'IT', 'CAT-IT', 'LMS Course Shell Provisioning & Academic Software Licensing Policy', '1.0', '2026-01-15', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Automated LMS roster synchronization and instructional lab software seat allocation.', '[SYNTHETIC DEMONSTRATION POLICY] LMS course shells are provisioned 30 days before term start and synchronize roster changes every 4 hours with the Registrar feed. Special seat allocations for instructional lab software are fulfilled by the Campus IT Operations & Identity Desk.', 'Section 6.1', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-it-2026-003', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-15T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-IT-2026-004', 'IT', 'CAT-IT', 'Student Hardware Loaner & Digital Device Support Policy', '1.0', '2026-01-15', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Term loaner laptop eligibility, checkout periods, and replacement liabilities.', '[SYNTHETIC DEMONSTRATION POLICY] Full-time enrolled students without computing hardware may request semester laptop loaners through Campus IT Operations. Hardware checkouts are subject to financial hardship verification and must be returned within 48 hours of term conclusion.', 'Section 4.1', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-it-2026-004', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-15T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-IT-2026-005', 'IT', 'CAT-IT', 'Instructional Software Licensing & High-Performance Compute Cluster Access', '1.0', '2026-01-15', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] GPU cluster access, MATLAB/SPSS campus licenses, and storage allocations.', '[SYNTHETIC DEMONSTRATION POLICY] Access to specialized departmental high-performance compute clusters and floating software licenses is provisioned to enrolled STEM and research students based on faculty sponsor endorsement.', 'Section 7.3', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-it-2026-005', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-15T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-IT-2026-006', 'IT', 'CAT-IT', 'Acceptable Network Use, Cybersecurity Incident & Vulnerability Reporting', '1.0', '2026-01-15', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Campus network monitoring, banned protocol policies, and mandatory incident reporting.', '[SYNTHETIC DEMONSTRATION POLICY] Connecting unauthorized network infrastructure, running port scans, or hosting pirated content on the campus network is strictly prohibited. Confirmed security incidents trigger immediate port isolation and referral to the Information Security Unit.', 'Section 9.2', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-it-2026-006', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-15T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-ACCESS-2026-001', 'ACCESS', 'CAT-ACCESS', 'Academic Accommodations & Testing Notice Policy (Legacy)', '1.0', '2025-01-01', '2026-06-15', 'expired', NULL, 'POL-ACCESS-2026-002', '[SYNTHETIC DEMONSTRATION POLICY — EXPIRED] Legacy 14-day proctored testing notice requirement expired June 15, 2026.', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-06-15), students were required to submit proctored exam accommodation booking requests 14 calendar days prior to the examination date.', 'Section 7.1 (Superseded)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-access-2026-001', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2025-01-01T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-ACCESS-2026-002', 'ACCESS', 'CAT-ACCESS', 'Academic Accommodations & Proctored Testing Notice Policy', '2.0', '2026-06-16', NULL, 'active', 'POL-ACCESS-2026-001', NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Current 5-business-day proctored exam notice, accommodation letters, and Section 504 escalation.', '[SYNTHETIC DEMONSTRATION POLICY] Effective June 16, 2026 (Version 2.0, superseding POL-ACCESS-2026-001 v1.0), students holding approved accommodation letters from the Disability & Accessibility Services Office must submit proctored exam scheduling requests at least 5 business days before the exam. Accommodation implementation disputes, denials, or urgent barrier reports must be escalated to the ADA / Section 504 Compliance Review Panel.', 'Section 7.2 (Current)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-access-2026-002', '2026.10-seed-20261022-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-06-16T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-ACCESS-2026-003', 'ACCESS', 'CAT-ACCESS', 'Assistive Technology, Real-Time Captioning & Accessible Media Policy', '1.0', '2026-01-15', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Provisioning of screen-reader compatible course packets, CART captioning, and ergonomic classroom seating.', '[SYNTHETIC DEMONSTRATION POLICY] The Disability & Accessibility Services Office coordinates real-time CART captioning, Braille/tactile graphics conversion, and screen-reader accessible PDF remediation for enrolled learners within 3 business days of request intake.', 'Section 8.3', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-access-2026-003', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-15T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-ACCESS-2026-004', 'ACCESS', 'CAT-ACCESS', 'Emotional Support Animal (ESA) & Campus Housing Accommodation Policy', '1.0', '2026-01-15', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] ESA verification, veterinary health records, and residence hall accommodation approval.', '[SYNTHETIC DEMONSTRATION POLICY] Approved emotional support animals in university housing require documentation from a licensed mental health clinician and up-to-date rabies vaccination records submitted at least 30 calendar days prior to move-in.', 'Section 4.5', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-access-2026-004', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-15T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-ACCESS-2026-005', 'ACCESS', 'CAT-ACCESS', 'Peer Note-Taking Services & Lecture Audio Recording Policy', '1.0', '2026-01-15', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Provision of anonymous peer note-takers and non-disclosure audio recording agreements.', '[SYNTHETIC DEMONSTRATION POLICY] Students authorized for peer note-taking receive anonymized lecture notes uploaded to the portal within 24 hours of each class session. Audio recording of lectures is permitted exclusively for personal educational use upon signing the institutional disability agreement.', 'Section 6.1', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-access-2026-005', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-15T13:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('POL-ACCESS-2026-006', 'ACCESS', 'CAT-ACCESS', 'Campus Physical Access Barrier Remediation & Temporary Mobility Requests', '1.0', '2026-01-15', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Urgent barrier reporting, elevator outages, and temporary paratransit shuttle passes.', '[SYNTHETIC DEMONSTRATION POLICY] Physical access barriers (e.g. elevator breakdown, power door failure) must be triaged as urgent requests by Disability Services within 2 business hours, with temporary accessible classroom relocation arranged if needed.', 'Section 9.4', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-access-2026-006', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-15T13:30:00+05:30', '2026-09-01T13:30:00+05:30')
