VALUES
  ('KB-000001', 'CAT-FINAID', 'POL-FINAID-2026-001', '1.0', 'SAP Pace of Completion Calculation & Appeal Packet Checklist (Ref POL-FINAID-2026-001 v1.0 · #1)', '1.0', '2025-01-01', '2026-06-30', 'expired', '[EXPIRED KNOWLEDGE ARTICLE] Operational guidance for sap pace of completion calculation & appeal packet checklist governed by POL-FINAID-2026-001 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-06-30), students placed on financial aid suspension had 10 calendar days from term start to submit a Satisfactory Academic Progress (SAP) appeal with supporting documentation to the Office of Financial Aid & Scholarships. Operational Article KB-000001 (v1.0) specifies step-by-step intake verification for SAP Pace of Completion Calculation & Appeal Packet Checklist. Governing Policy: POL-FINAID-2026-001 v1.0 (Section 4.1 (Superseded)).', ARRAY['finaid', 'pol-finaid-2026-001', 'expired-reference']::text[], 'urn:campusresolve:synthetic-kb:kb-000001', '2026.10-seed-20261022-kb-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2025-01-01T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000002', 'CAT-FINAID', 'POL-FINAID-2026-002', '2.0', 'Federal & Institutional Grant Disbursement Hold Resolution (Ref POL-FINAID-2026-002 v2.0 · #2)', '2.0', '2026-07-01', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for federal & institutional grant disbursement hold resolution governed by POL-FINAID-2026-002 (v2.0).', '[SYNTHETIC DEMONSTRATION POLICY] Effective July 1, 2026 (Version 2.0, superseding POL-FINAID-2026-001 v1.0), students whose cumulative GPA falls below 2.0 or pace of completion falls below 67% may submit a written Satisfactory Academic Progress (SAP) appeal within 15 business days of notification. Standard eligibility verifications are handled by the Office of Financial Aid & Scholarships; second-level SAP appeals and emergency statutory waivers must be escalated to the Financial Aid Appeals & Compliance Review Committee. Operational Article KB-000002 (v2.0) specifies step-by-step intake verification for Federal & Institutional Grant Disbursement Hold Resolution. Governing Policy: POL-FINAID-2026-002 v2.0 (Section 4.2 (Current)).', ARRAY['finaid', 'pol-finaid-2026-002', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000002', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-07-01T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000003', 'CAT-FINAID', 'POL-FINAID-2026-003', '1.0', 'Census Date Credit Hour Proration for Half-Time Learners (Ref POL-FINAID-2026-003 v1.0 · #3)', '2.0', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for census date credit hour proration for half-time learners governed by POL-FINAID-2026-003 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Institutional grants and federal aid disburse no earlier than 10 days prior to the official term start date, contingent upon active enrollment in at least 6 credit hours for half-time status or 12 credit hours for full-time status locked at the add/drop census deadline. Operational Article KB-000003 (v2.0) specifies step-by-step intake verification for Census Date Credit Hour Proration for Half-Time Learners. Governing Policy: POL-FINAID-2026-003 v1.0 (Section 2.3).', ARRAY['finaid', 'pol-finaid-2026-003', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000003', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000004', 'CAT-FINAID', 'POL-FINAID-2026-004', '1.0', 'Emergency Hardship Financial Aid Re-Evaluation Procedure (Ref POL-FINAID-2026-004 v1.0 · #4)', '2.0', '2026-02-01', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for emergency hardship financial aid re-evaluation procedure governed by POL-FINAID-2026-004 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Students experiencing acute financial disruption may petition for emergency grant disbursements of up to $2,500. Note: Section 5.1 permits emergency disbursements within 48 business hours of verification, representing a priority exception to standard census proration rules under POL-FINAID-2026-003. Operational Article KB-000004 (v2.0) specifies step-by-step intake verification for Emergency Hardship Financial Aid Re-Evaluation Procedure. Governing Policy: POL-FINAID-2026-004 v1.0 (Section 5.1 (Conflicting Provision)).', ARRAY['finaid', 'pol-finaid-2026-004', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000004', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-02-01T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000005', 'CAT-FINAID', 'POL-FINAID-2026-005', '1.0', 'Merit Scholarship Renewal GPA Verification & Grace Term Rules (Ref POL-FINAID-2026-005 v1.0 · #5)', '2.1', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for merit scholarship renewal gpa verification & grace term rules governed by POL-FINAID-2026-005 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Institutional merit scholarships require a minimum cumulative GPA of 3.20 evaluated at the end of each spring semester. Learners failing the threshold receive one probationary grace semester before award cancellation. Operational Article KB-000005 (v2.1) specifies step-by-step intake verification for Merit Scholarship Renewal GPA Verification & Grace Term Rules. Governing Policy: POL-FINAID-2026-005 v1.0 (Section 3.4).', ARRAY['finaid', 'pol-finaid-2026-005', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000005', '2026.10-seed-20261022-kb-v2.1', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000006', 'CAT-FINAID', 'POL-FINAID-2026-006', '1.0', 'International Student Emergency Fellowship Application Guide (Ref POL-FINAID-2026-006 v1.0 · #6)', '2.0', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for international student emergency fellowship application guide governed by POL-FINAID-2026-006 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] International students holding F-1/J-1 visas may receive departmental fellowships and emergency campus employment awards up to 20 hours per week during academic terms, subject to International Student Center immigration verification. Operational Article KB-000006 (v2.0) specifies step-by-step intake verification for International Student Emergency Fellowship Application Guide. Governing Policy: POL-FINAID-2026-006 v1.0 (Section 6.2).', ARRAY['finaid', 'pol-finaid-2026-006', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000006', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000007', 'CAT-REG', 'POL-REG-2026-001', '1.0', 'Grade Forgiveness Course Repetition Petition and GPA Replacement (Ref POL-REG-2026-001 v1.0 · #7)', '1.0', '2025-01-01', '2026-05-31', 'expired', '[EXPIRED KNOWLEDGE ARTICLE] Operational guidance for grade forgiveness course repetition petition and gpa replacement governed by POL-REG-2026-001 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-05-31), students could drop courses without a W grade through Week 3 of the semester. Operational Article KB-000007 (v1.0) specifies step-by-step intake verification for Grade Forgiveness Course Repetition Petition and GPA Replacement. Governing Policy: POL-REG-2026-001 v1.0 (Section 3.1 (Superseded)).', ARRAY['reg', 'pol-reg-2026-001', 'expired-reference']::text[], 'urn:campusresolve:synthetic-kb:kb-000007', '2026.10-seed-20261022-kb-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2025-01-01T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000008', 'CAT-REG', 'POL-REG-2026-002', '2.0', 'Independent Study Syllabus and Department Chair Authorization (Ref POL-REG-2026-002 v2.0 · #8)', '2.0', '2026-06-01', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for independent study syllabus and department chair authorization governed by POL-REG-2026-002 (v2.0).', '[SYNTHETIC DEMONSTRATION POLICY] Effective June 1, 2026 (Version 2.0, superseding POL-REG-2026-001 v1.0), standard course additions and drops without transcript notation must be completed within the first 10 business days of the term via the Office of the University Registrar. Course withdrawals with a W notation are permitted through the end of Week 8. Any retroactive withdrawal or late drop petition after Week 8 requires documented extenuating circumstances and mandatory escalation to the Academic Senate Registration Review Board. Operational Article KB-000008 (v2.0) specifies step-by-step intake verification for Independent Study Syllabus and Department Chair Authorization. Governing Policy: POL-REG-2026-002 v2.0 (Section 3.2 (Current)).', ARRAY['reg', 'pol-reg-2026-002', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000008', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-06-01T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000009', 'CAT-REG', 'POL-REG-2026-003', '1.0', 'First-10-Business-Day Add/Drop Procedure & Roster Lock (Ref POL-REG-2026-003 v1.0 · #9)', '2.0', '2026-01-10', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for first-10-business-day add/drop procedure & roster lock governed by POL-REG-2026-003 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Standard undergraduate enrollment is capped at 18 credit hours per regular term. Requests to enroll in 19 to 22 credit hours require a minimum cumulative GPA of 3.30 and advisor attestation processed by the Office of the University Registrar. Operational Article KB-000009 (v2.0) specifies step-by-step intake verification for First-10-Business-Day Add/Drop Procedure & Roster Lock. Governing Policy: POL-REG-2026-003 v1.0 (Section 5.4).', ARRAY['reg', 'pol-reg-2026-003', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000009', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-10T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000010', 'CAT-REG', 'POL-REG-2026-004', '1.0', 'Week 8 Course Withdrawal (W Grade) Online Submission Guide (Ref POL-REG-2026-004 v1.0 · #10)', '2.1', '2026-01-10', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for week 8 course withdrawal (w grade) online submission guide governed by POL-REG-2026-004 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Undergraduate students may repeat up to 3 courses (maximum 12 credit hours) for grade replacement. The second earned grade replaces the initial grade in cumulative GPA computation, though all attempts remain permanently visible on transcript. Operational Article KB-000010 (v2.1) specifies step-by-step intake verification for Week 8 Course Withdrawal (W Grade) Online Submission Guide. Governing Policy: POL-REG-2026-004 v1.0 (Section 4.3).', ARRAY['reg', 'pol-reg-2026-004', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000010', '2026.10-seed-20261022-kb-v2.1', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-10T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000011', 'CAT-REG', 'POL-REG-2026-005', '1.0', 'Post-Deadline Retroactive Withdrawal Petition Documentation (Ref POL-REG-2026-005 v1.0 · #11)', '2.0', '2026-01-10', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for post-deadline retroactive withdrawal petition documentation governed by POL-REG-2026-005 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Enrolling in independent study courses requires a structured syllabus, supervising faculty signature, and department chair approval filed with the Registrar no later than the add/drop census date. Operational Article KB-000011 (v2.0) specifies step-by-step intake verification for Post-Deadline Retroactive Withdrawal Petition Documentation. Governing Policy: POL-REG-2026-005 v1.0 (Section 7.1).', ARRAY['reg', 'pol-reg-2026-005', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000011', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-10T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000012', 'CAT-REG', 'POL-REG-2026-006', '1.0', 'Undergraduate 19–22 Credit Hour Overload Approval Workflow (Ref POL-REG-2026-006 v1.0 · #12)', '2.0', '2026-01-10', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for undergraduate 19–22 credit hour overload approval workflow governed by POL-REG-2026-006 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Undergraduates with cumulative GPA below 2.00 are placed on academic probation. Two consecutive probationary terms trigger academic suspension, which may be appealed within 10 business days to the Dean of Academic Affairs. Operational Article KB-000012 (v2.0) specifies step-by-step intake verification for Undergraduate 19–22 Credit Hour Overload Approval Workflow. Governing Policy: POL-REG-2026-006 v1.0 (Section 8.2).', ARRAY['reg', 'pol-reg-2026-006', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000012', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-10T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000013', 'CAT-IT', 'POL-IT-2026-001', '1.0', 'Student Hardware Loaner Laptop Checkout Eligibility and Return Rules (Ref POL-IT-2026-001 v1.0 · #13)', '1.0', '2025-01-01', '2026-04-30', 'expired', '[EXPIRED KNOWLEDGE ARTICLE] Operational guidance for student hardware loaner laptop checkout eligibility and return rules governed by POL-IT-2026-001 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-04-30), SMS text codes were permitted as a primary multi-factor authentication method for institutional accounts. Operational Article KB-000013 (v1.0) specifies step-by-step intake verification for Student Hardware Loaner Laptop Checkout Eligibility and Return Rules. Governing Policy: POL-IT-2026-001 v1.0 (Section 1.1 (Superseded)).', ARRAY['it', 'pol-it-2026-001', 'expired-reference']::text[], 'urn:campusresolve:synthetic-kb:kb-000013', '2026.10-seed-20261022-kb-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2025-01-01T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000014', 'CAT-IT', 'POL-IT-2026-002', '2.0', 'Reporting Suspected Phishing, Token Theft or Credential Compromise (Ref POL-IT-2026-002 v2.0 · #14)', '2.0', '2026-05-01', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for reporting suspected phishing, token theft or credential compromise governed by POL-IT-2026-002 (v2.0).', '[SYNTHETIC DEMONSTRATION POLICY] Effective May 1, 2026 (Version 2.0, superseding POL-IT-2026-001 v1.0), all learners, instructors, and staff must use FIDO2 passkeys or TOTP authenticator apps for Single Sign-On (SSO). Routine MFA device resets are handled by the Campus IT Operations & Identity Desk after photo-ID verification. Suspected account compromise or privilege anomalies must be escalated immediately to the Information Security & Infrastructure Escalation Unit. Operational Article KB-000014 (v2.0) specifies step-by-step intake verification for Reporting Suspected Phishing, Token Theft or Credential Compromise. Governing Policy: POL-IT-2026-002 v2.0 (Section 1.2 (Current)).', ARRAY['it', 'pol-it-2026-002', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000014', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-05-01T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000015', 'CAT-IT', 'POL-IT-2026-003', '1.0', 'Departmental High-Performance GPU Cluster Access Sponsorship (Ref POL-IT-2026-003 v1.0 · #15)', '2.1', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for departmental high-performance gpu cluster access sponsorship governed by POL-IT-2026-003 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] LMS course shells are provisioned 30 days before term start and synchronize roster changes every 4 hours with the Registrar feed. Special seat allocations for instructional lab software are fulfilled by the Campus IT Operations & Identity Desk. Operational Article KB-000015 (v2.1) specifies step-by-step intake verification for Departmental High-Performance GPU Cluster Access Sponsorship. Governing Policy: POL-IT-2026-003 v1.0 (Section 6.1).', ARRAY['it', 'pol-it-2026-003', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000015', '2026.10-seed-20261022-kb-v2.1', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000016', 'CAT-IT', 'POL-IT-2026-004', '1.0', 'Campus Wi-Fi Connectivity and Rogue Access Point Restriction (Ref POL-IT-2026-004 v1.0 · #16)', '2.0', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for campus wi-fi connectivity and rogue access point restriction governed by POL-IT-2026-004 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Full-time enrolled students without computing hardware may request semester laptop loaners through Campus IT Operations. Hardware checkouts are subject to financial hardship verification and must be returned within 48 hours of term conclusion. Operational Article KB-000016 (v2.0) specifies step-by-step intake verification for Campus Wi-Fi Connectivity and Rogue Access Point Restriction. Governing Policy: POL-IT-2026-004 v1.0 (Section 4.1).', ARRAY['it', 'pol-it-2026-004', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000016', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000017', 'CAT-IT', 'POL-IT-2026-005', '1.0', 'Transitioning from Legacy SMS to FIDO2 / TOTP Authenticator MFA (Ref POL-IT-2026-005 v1.0 · #17)', '2.0', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for transitioning from legacy sms to fido2 / totp authenticator mfa governed by POL-IT-2026-005 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Access to specialized departmental high-performance compute clusters and floating software licenses is provisioned to enrolled STEM and research students based on faculty sponsor endorsement. Operational Article KB-000017 (v2.0) specifies step-by-step intake verification for Transitioning from Legacy SMS to FIDO2 / TOTP Authenticator MFA. Governing Policy: POL-IT-2026-005 v1.0 (Section 7.3).', ARRAY['it', 'pol-it-2026-005', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000017', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000018', 'CAT-IT', 'POL-IT-2026-006', '1.0', 'Identity Verification for Locked Institutional SSO Accounts (Ref POL-IT-2026-006 v1.0 · #18)', '2.0', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for identity verification for locked institutional sso accounts governed by POL-IT-2026-006 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Connecting unauthorized network infrastructure, running port scans, or hosting pirated content on the campus network is strictly prohibited. Confirmed security incidents trigger immediate port isolation and referral to the Information Security Unit. Operational Article KB-000018 (v2.0) specifies step-by-step intake verification for Identity Verification for Locked Institutional SSO Accounts. Governing Policy: POL-IT-2026-006 v1.0 (Section 9.2).', ARRAY['it', 'pol-it-2026-006', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000018', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000019', 'CAT-ACCESS', 'POL-ACCESS-2026-001', '1.0', 'Instructor Notification Letters for Approved Exam Extended Time (Ref POL-ACCESS-2026-001 v1.0 · #19)', '1.0', '2025-01-01', '2026-06-15', 'expired', '[EXPIRED KNOWLEDGE ARTICLE] Operational guidance for instructor notification letters for approved exam extended time governed by POL-ACCESS-2026-001 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-06-15), students were required to submit proctored exam accommodation booking requests 14 calendar days prior to the examination date. Operational Article KB-000019 (v1.0) specifies step-by-step intake verification for Instructor Notification Letters for Approved Exam Extended Time. Governing Policy: POL-ACCESS-2026-001 v1.0 (Section 7.1 (Superseded)).', ARRAY['access', 'pol-access-2026-001', 'expired-reference']::text[], 'urn:campusresolve:synthetic-kb:kb-000019', '2026.10-seed-20261022-kb-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2025-01-01T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000020', 'CAT-ACCESS', 'POL-ACCESS-2026-002', '2.0', 'Escalating Accommodation Implementation Barriers to Section 504 Panel (Ref POL-ACCESS-2026-002 v2.0 · #20)', '2.1', '2026-06-16', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for escalating accommodation implementation barriers to section 504 panel governed by POL-ACCESS-2026-002 (v2.0).', '[SYNTHETIC DEMONSTRATION POLICY] Effective June 16, 2026 (Version 2.0, superseding POL-ACCESS-2026-001 v1.0), students holding approved accommodation letters from the Disability & Accessibility Services Office must submit proctored exam scheduling requests at least 5 business days before the exam. Accommodation implementation disputes, denials, or urgent barrier reports must be escalated to the ADA / Section 504 Compliance Review Panel. Operational Article KB-000020 (v2.1) specifies step-by-step intake verification for Escalating Accommodation Implementation Barriers to Section 504 Panel. Governing Policy: POL-ACCESS-2026-002 v2.0 (Section 7.2 (Current)).', ARRAY['access', 'pol-access-2026-002', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000020', '2026.10-seed-20261022-kb-v2.1', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-06-16T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000021', 'CAT-ACCESS', 'POL-ACCESS-2026-003', '1.0', 'Assistive Screen-Reader PDF Remediation Turnaround Standards (Ref POL-ACCESS-2026-003 v1.0 · #21)', '2.0', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for assistive screen-reader pdf remediation turnaround standards governed by POL-ACCESS-2026-003 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] The Disability & Accessibility Services Office coordinates real-time CART captioning, Braille/tactile graphics conversion, and screen-reader accessible PDF remediation for enrolled learners within 3 business days of request intake. Operational Article KB-000021 (v2.0) specifies step-by-step intake verification for Assistive Screen-Reader PDF Remediation Turnaround Standards. Governing Policy: POL-ACCESS-2026-003 v1.0 (Section 8.3).', ARRAY['access', 'pol-access-2026-003', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000021', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000022', 'CAT-ACCESS', 'POL-ACCESS-2026-004', '1.0', 'Campus Housing Emotional Support Animal Health Record Clearance (Ref POL-ACCESS-2026-004 v1.0 · #22)', '2.0', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for campus housing emotional support animal health record clearance governed by POL-ACCESS-2026-004 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Approved emotional support animals in university housing require documentation from a licensed mental health clinician and up-to-date rabies vaccination records submitted at least 30 calendar days prior to move-in. Operational Article KB-000022 (v2.0) specifies step-by-step intake verification for Campus Housing Emotional Support Animal Health Record Clearance. Governing Policy: POL-ACCESS-2026-004 v1.0 (Section 4.5).', ARRAY['access', 'pol-access-2026-004', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000022', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000023', 'CAT-ACCESS', 'POL-ACCESS-2026-005', '1.0', 'Peer Note-Taking Services and Lecture Audio Recording Permissions (Ref POL-ACCESS-2026-005 v1.0 · #23)', '2.0', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for peer note-taking services and lecture audio recording permissions governed by POL-ACCESS-2026-005 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Students authorized for peer note-taking receive anonymized lecture notes uploaded to the portal within 24 hours of each class session. Audio recording of lectures is permitted exclusively for personal educational use upon signing the institutional disability agreement. Operational Article KB-000023 (v2.0) specifies step-by-step intake verification for Peer Note-Taking Services and Lecture Audio Recording Permissions. Governing Policy: POL-ACCESS-2026-005 v1.0 (Section 6.1).', ARRAY['access', 'pol-access-2026-005', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000023', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T14:30:00+05:30', '2026-09-01T13:30:00+05:30'),
  ('KB-000024', 'CAT-ACCESS', 'POL-ACCESS-2026-006', '1.0', 'Reporting Physical Mobility Obstacles and Accessible Van Booking (Ref POL-ACCESS-2026-006 v1.0 · #24)', '2.0', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for reporting physical mobility obstacles and accessible van booking governed by POL-ACCESS-2026-006 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Physical access barriers (e.g. elevator breakdown, power door failure) must be triaged as urgent requests by Disability Services within 2 business hours, with temporary accessible classroom relocation arranged if needed. Operational Article KB-000024 (v2.0) specifies step-by-step intake verification for Reporting Physical Mobility Obstacles and Accessible Van Booking. Governing Policy: POL-ACCESS-2026-006 v1.0 (Section 9.4).', ARRAY['access', 'pol-access-2026-006', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000024', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T14:30:00+05:30', '2026-09-01T13:30:00+05:30')
