INSERT INTO public.tickets (ticket_id, requester_id, requester_profile_id, category_id, category_name, term_id, subject, description, priority, lifecycle_status, current_assigned_team, current_routing_rule_id, referenced_policy_id, referenced_policy_version, referenced_article_id, referenced_article_version, requires_escalation, is_escalated, escalation_reason, resolution_summary, is_synthetic_eval, submitted_at, updated_at, resolved_at, closed_at)
VALUES
  ('TKT-2026-000001', 'REQ-2026-000001', NULL, 'CAT-FINAID', 'Financial Aid', 'TERM-2026-FALL', 'Fee paid hai but portal pe pending dikha raha hai, please help (#1)', 'Fee paid hai online banking se yesterday morning, but student portal pe abhi bhi balance pending dikha raha hai. Registration hold lag jayega kya? Please check transaction and update ASAP. (Student ID: REQ-2026-000001, Course: CS-101, Term: TERM-2026-FALL).', 'Standard Priority', 'resolved', 'Office of Financial Aid & Scholarships', 'RULE-FINAID-001', 'POL-FINAID-2026-002', '2.0', 'KB-000002', '2.0', FALSE, FALSE, NULL, 'Resolved in accordance with POL-FINAID-2026-002 v2.0 (Section 4.2 (Current)) and KB-000002 v2.0.', TRUE, '2026-10-09T21:41:00+05:30', '2026-10-10T00:41:00+05:30', '2026-10-10T00:41:00+05:30', NULL),
  ('TKT-2026-000002', 'REQ-2026-000002', NULL, 'CAT-REG', 'Registration', 'TERM-2026-FALL', 'Course drop kiya tha still timetable me reflect ho raha hai, please check (#2)', 'Hi, I dropped one course MATH-215 yesterday before the deadline but it is still showing in my active timetable and Canvas. Please confirm if drop was successful. (Student ID: REQ-2026-000002, Course: EECS-280, Term: TERM-2026-FALL).', 'Standard Priority', 'under_review', 'Office of the University Registrar', 'RULE-REG-001', 'POL-REG-2026-003', '1.0', 'KB-000009', '2.0', FALSE, FALSE, NULL, NULL, TRUE, '2026-10-14T20:52:00+05:30', '2026-10-14T23:52:00+05:30', NULL, NULL),
  ('TKT-2026-000003', 'REQ-2026-000003', NULL, 'CAT-ACCESS', 'Accessibility', 'TERM-2026-FALL', 'screen reader pdf course packet formating broken and unreadable (#3)', 'The PDF packet uploaded for HIST-201 cannot be read by NVDA screen reader, image scans are missing OCR text. Need converted accessible file. (Student ID: REQ-2026-000003, Course: MATH-215, Term: TERM-2026-FALL).', 'Standard Priority', 'resolved', 'Disability & Accessibility Services Office', 'RULE-ACCESS-001', 'POL-ACCESS-2026-001', '1.0', 'KB-000019', '1.0', FALSE, FALSE, NULL, 'Resolved in accordance with POL-ACCESS-2026-001 v1.0 (Section 7.1 (Superseded)) and KB-000019 v1.0.', TRUE, '2026-10-19T20:03:00+05:30', '2026-10-19T23:03:00+05:30', '2026-10-19T23:03:00+05:30', NULL),
  ('TKT-2026-000004', 'REQ-2026-000004', NULL, 'CAT-FINAID', 'Financial Aid', 'TERM-2026-FALL', 'Dual issue: SAP appeal submission and tuition payment installment plan (#4)', 'I need to submit my Satisfactory Academic Progress appeal documentation following a medical leave, and simultaneously enroll in the monthly tuition installment plan before the census date. (Student ID: REQ-2026-000004, Course: BIO-172, Term: TERM-2026-FALL).', 'Standard Priority', 'under_review', 'Financial Aid Appeals & Compliance Review Committee', 'RULE-FINAID-001', 'POL-FINAID-2026-005', '1.0', 'KB-000005', '2.1', FALSE, FALSE, NULL, NULL, TRUE, '2026-10-29T19:14:00+05:30', '2026-10-29T22:14:00+05:30', NULL, NULL),
  ('TKT-2026-000005', 'REQ-2026-000005', NULL, 'CAT-REG', 'Registration', 'TERM-2026-FALL', 'I am not sure whether I should submit the withdrawal form or appeal first (#5)', 'My grade is very low in one subject and week 8 is ending. What is the process to withdraw without hurting my record? (Student ID: REQ-2026-000005, Course: ECON-101, Term: TERM-2026-FALL).', 'Time-Sensitive Academic Priority', 'resolved', 'Academic Senate Registration Review Board', 'RULE-REG-001', 'POL-REG-2026-006', '1.0', 'KB-000012', '2.0', FALSE, FALSE, NULL, 'Resolved in accordance with POL-REG-2026-006 v1.0 (Section 8.2) and KB-000012 v2.0.', TRUE, '2026-11-03T18:25:00+05:30', '2026-11-03T21:25:00+05:30', '2026-11-03T21:25:00+05:30', NULL),
  ('TKT-2026-000006', 'REQ-2026-000006', NULL, 'CAT-ACCESS', 'Accessibility', 'TERM-2026-FALL', 'Formal Section 504 Grievance: Denial of approved exam accommodation (#6)', 'Submitting formal administrative escalation to ADA / Section 504 Compliance Review Panel regarding course instructor refusal to honor approved distraction-reduced testing environment. (Student ID: REQ-2026-000006, Course: CHEM-130, Term: TERM-2026-FALL).', 'Standard Priority', 'under_review', 'Disability & Accessibility Services Office', 'RULE-ACCESS-001', 'POL-ACCESS-2026-002', '2.0', 'KB-000020', '2.1', FALSE, FALSE, NULL, NULL, TRUE, '2026-11-13T16:36:00+05:30', '2026-11-13T19:36:00+05:30', NULL, NULL),
  ('TKT-2026-000007', 'REQ-2026-000007', NULL, 'CAT-REG', 'Registration', 'TERM-2026-FALL', 'Petition for 20 Credit Hour Undergraduate Overload (GPA 3.65) [ENG-125 · Ref #7]', 'Submitting request for credit overload to enroll in 20 semester hours to complete dual-degree requirements. Cumulative GPA 3.65 with signed faculty advisor attestation. (Student ID: REQ-2026-000007, Course: ENG-125, Term: TERM-2026-FALL).', 'Standard Priority', 'resolved', 'Office of Financial Aid & Scholarships', 'RULE-FINAID-001', 'POL-REG-2026-003', '1.0', 'KB-000009', '2.0', FALSE, FALSE, NULL, 'Resolved in accordance with POL-REG-2026-003 v1.0 (Section 5.4) and KB-000009 v2.0.', TRUE, '2026-11-18T15:47:00+05:30', '2026-11-18T18:47:00+05:30', '2026-11-18T18:47:00+05:30', NULL),
  ('TKT-2026-000008', 'REQ-2026-000008', NULL, 'CAT-IT', 'IT', 'TERM-2026-FALL', 'My account is locked and I have an assignment submission today (#8)', 'My university SSO account got locked after multiple failed attempts and my final project submission deadline is in 3 hours on Canvas LMS. Please reset my MFA access urgently! (Student ID: REQ-2026-000008, Course: PHYS-240, Term: TERM-2026-FALL).', 'Standard Priority', 'policy_verified', 'Campus IT Operations & Identity Desk', 'RULE-IT-001', 'POL-IT-2026-004', '1.0', 'KB-000016', '2.0', FALSE, FALSE, NULL, NULL, TRUE, '2026-11-23T14:58:00+05:30', '2026-11-23T17:58:00+05:30', NULL, NULL),
  ('TKT-2026-000009', 'REQ-2026-000009', NULL, 'CAT-FINAID', 'Financial Aid', 'TERM-2026-FALL', 'Urgent: Scholarship disbursement hold with fee deadline today (#9)', 'My merit scholarship of $3,500 has not been disbursed and the tuition payment deadline is 5:00 PM today. A late fee will be charged if this hold is not cleared immediately. (Student ID: REQ-2026-000009, Course: CS-101, Term: TERM-2026-FALL).', 'Standard Priority', 'resolved', 'Office of Financial Aid & Scholarships', 'RULE-FINAID-001', 'POL-FINAID-2026-005', '1.0', 'KB-000005', '2.1', FALSE, FALSE, NULL, 'Resolved in accordance with POL-FINAID-2026-005 v1.0 (Section 3.4) and KB-000005 v2.1.', TRUE, '2026-12-03T22:09:00+05:30', '2026-12-04T01:09:00+05:30', '2026-12-04T01:09:00+05:30', NULL),
  ('TKT-2026-000010', 'REQ-2026-000010', NULL, 'CAT-REG', 'Registration', 'TERM-2026-FALL', 'regsitration portal throwng error for credit overload (#10)', 'I am tryng to register for 19 credits with 3.4 GPA but regsitration system says max credit limit 18 reached. Need overload approval. (Student ID: REQ-2026-000010, Course: EECS-280, Term: TERM-2026-FALL).', 'Time-Sensitive Academic Priority', 'policy_verified', 'Office of the University Registrar', 'RULE-REG-001', 'POL-REG-2026-006', '1.0', 'KB-000012', '2.0', FALSE, FALSE, NULL, NULL, TRUE, '2026-12-08T21:20:00+05:30', '2026-12-09T00:20:00+05:30', NULL, NULL),
  ('TKT-2026-000011', 'REQ-2026-000011', NULL, 'CAT-IT', 'IT', 'TERM-2026-FALL', 'Laptop loaner request for term and Canvas LMS enrollment missing for BIO-172 (#11)', 'My personal laptop broke and I need to request an IT semester loaner device, and also my registration for BIO-172 is not syncing to my Canvas course list. (Student ID: REQ-2026-000011, Course: MATH-215, Term: TERM-2026-FALL).', 'Standard Priority', 'resolved', 'Campus IT Operations & Identity Desk', 'RULE-IT-001', 'POL-IT-2026-002', '2.0', 'KB-000014', '2.0', FALSE, FALSE, NULL, 'UNSUPPORTED CLAIM: Approved automatic 100% full tuition refund and 45-day retroactive deadline extension without documentation.', TRUE, '2026-08-28T19:31:00+05:30', '2026-08-28T22:31:00+05:30', '2026-08-28T22:31:00+05:30', NULL),
  ('TKT-2026-000012', 'REQ-2026-000012', NULL, 'CAT-FINAID', 'Financial Aid', 'TERM-2026-FALL', 'Financial aid question please check (#12)', 'Can someone check my account? Something looks wrong with the total amount for Fall semester. (Student ID: REQ-2026-000012, Course: BIO-172, Term: TERM-2026-FALL).', 'Administrative Escalation Priority', 'escalated', 'Financial Aid Appeals & Compliance Review Committee', 'RULE-FINAID-001', 'POL-FINAID-2026-003', '1.0', 'KB-000003', '2.0', TRUE, TRUE, 'Request submitted with Administrative Escalation Priority.', NULL, TRUE, '2026-09-02T18:42:00+05:30', '2026-09-02T21:42:00+05:30', NULL, NULL),
  ('TKT-2026-000013', 'REQ-2026-000013', NULL, 'CAT-REG', 'Registration', 'TERM-2026-FALL', 'Academic Senate Retroactive Withdrawal Petition post Week-8 deadline (#13)', 'Formal petition for retroactive late withdrawal with W grade notation following unexpected emergency surgery. Submitting attending surgeon documentation for Academic Senate review. (Student ID: REQ-2026-000013, Course: ECON-101, Term: TERM-2026-FALL).', 'Standard Priority', 'resolved', 'Academic Senate Registration Review Board', 'RULE-REG-001', 'POL-REG-2026-004', '1.0', 'KB-000010', '2.1', FALSE, FALSE, NULL, 'Resolved in accordance with POL-REG-2026-004 v1.0 (Section 4.3) and KB-000010 v2.1.', TRUE, '2026-09-07T17:53:00+05:30', '2026-09-07T20:53:00+05:30', '2026-09-07T20:53:00+05:30', NULL),
  ('TKT-2026-000014', 'REQ-2026-000014', NULL, 'CAT-ACCESS', 'Accessibility', 'TERM-2026-FALL', 'Request for Real-Time CART Captioning Provider for Lecture Series [CHEM-130 · Ref #14]', 'Approved accommodation request for real-time CART captioning for daily 10:00 AM lecture. Course syllabus and classroom schedule submitted for scheduling. (Student ID: REQ-2026-000014, Course: CHEM-130, Term: TERM-2026-FALL).', 'Standard Priority', 'closed', 'Disability & Accessibility Services Office', 'RULE-ACCESS-001', 'POL-ACCESS-2026-005', '1.0', 'KB-000023', '2.0', FALSE, FALSE, NULL, 'Resolved in accordance with POL-ACCESS-2026-005 v1.0 (Section 6.1) and KB-000023 v2.0.', TRUE, '2026-09-17T17:04:00+05:30', '2026-09-17T20:04:00+05:30', '2026-09-17T20:04:00+05:30', '2026-09-18T20:04:00+05:30'),
