  ('TKT-2026-000045', 'REQ-2026-000020', NULL, 'CAT-REG', 'Registration', 'TERM-2026-FALL', 'regsitration portal throwng error for credit overload (#45)', 'I am tryng to register for 19 credits with 3.4 GPA but regsitration system says max credit limit 18 reached. Need overload approval. (Student ID: REQ-2026-000020, Course: ECON-101, Term: TERM-2026-FALL).', 'Time-Sensitive Academic Priority', 'resolved', 'Office of the University Registrar', 'RULE-REG-001', 'POL-REG-2026-006', '1.0', 'KB-000012', '2.0', FALSE, FALSE, NULL, 'Resolved in accordance with POL-REG-2026-006 v1.0 (Section 8.2) and KB-000012 v2.0.', TRUE, '2026-09-08T17:45:00+05:30', '2026-09-08T20:45:00+05:30', '2026-09-08T20:45:00+05:30', NULL),
  ('TKT-2026-000046', 'REQ-2026-000021', NULL, 'CAT-IT', 'IT', 'TERM-2026-FALL', 'Laptop loaner request for term and Canvas LMS enrollment missing for BIO-172 (#46)', 'My personal laptop broke and I need to request an IT semester loaner device, and also my registration for BIO-172 is not syncing to my Canvas course list. (Student ID: REQ-2026-000021, Course: CHEM-130, Term: TERM-2026-FALL).', 'Standard Priority', 'submitted', 'Campus IT Operations & Identity Desk', 'RULE-IT-001', 'POL-IT-2026-002', '2.0', 'KB-000014', '2.0', FALSE, FALSE, NULL, NULL, TRUE, '2026-09-18T16:56:00+05:30', '2026-09-18T19:56:00+05:30', NULL, NULL),
  ('TKT-2026-000047', 'REQ-2026-000022', NULL, 'CAT-FINAID', 'Financial Aid', 'TERM-2026-FALL', 'Financial aid question please check (#47)', 'Can someone check my account? Something looks wrong with the total amount for Fall semester. (Student ID: REQ-2026-000022, Course: ENG-125, Term: TERM-2026-FALL).', 'Standard Priority', 'resolved', 'Office of Financial Aid & Scholarships', 'RULE-FINAID-001', 'POL-FINAID-2026-003', '1.0', 'KB-000003', '2.0', FALSE, FALSE, NULL, 'Resolved in accordance with POL-FINAID-2026-003 v1.0 (Section 2.3) and KB-000003 v2.0.', TRUE, '2026-09-23T16:07:00+05:30', '2026-09-23T19:07:00+05:30', '2026-09-23T19:07:00+05:30', NULL),
  ('TKT-2026-000048', 'REQ-2026-000023', NULL, 'CAT-REG', 'Registration', 'TERM-2026-FALL', 'Registration Formal Appeal Petition: Grade Forgiveness & Course Repetition Regulations (POL-REG-2026-004)', 'Formal petition for retroactive late withdrawal with W grade notation following unexpected emergency surgery. Submitting attending surgeon documentation for Academic Senate review. (Student ID: REQ-2026-000023, Course: PHYS-240, Term: TERM-2026-FALL).', 'Administrative Escalation Priority', 'escalated', 'Academic Senate Registration Review Board', 'RULE-REG-001', 'POL-REG-2026-004', '1.0', 'KB-000010', '2.1', TRUE, TRUE, 'Request submitted with Administrative Escalation Priority. Request text contains policy exception, formal appeal, or retroactive petition criteria requiring administrative review.', NULL, TRUE, '2026-09-28T15:18:00+05:30', '2026-09-28T18:18:00+05:30', NULL, NULL),
  ('TKT-2026-000049', 'REQ-2026-000024', NULL, 'CAT-ACCESS', 'Accessibility', 'TERM-2026-FALL', 'Request for Real-Time CART Captioning Provider for Lecture Series [CS-101 · Ref #49]', 'Approved accommodation request for real-time CART captioning for daily 10:00 AM lecture. Course syllabus and classroom schedule submitted for scheduling. (Student ID: REQ-2026-000024, Course: CS-101, Term: TERM-2026-FALL).', 'Standard Priority', 'resolved', 'Disability & Accessibility Services Office', 'RULE-ACCESS-001', 'POL-ACCESS-2026-005', '1.0', 'KB-000023', '2.0', FALSE, FALSE, NULL, 'Resolved in accordance with POL-ACCESS-2026-005 v1.0 (Section 6.1) and KB-000023 v2.0.', TRUE, '2026-10-08T22:29:00+05:30', '2026-10-09T01:29:00+05:30', '2026-10-09T01:29:00+05:30', NULL),
  ('TKT-2026-000050', 'REQ-2026-000025', NULL, 'CAT-FINAID', 'Financial Aid', 'TERM-2026-FALL', 'Fee paid hai but portal pe pending dikha raha hai, please help (#50)', 'Fee paid hai online banking se yesterday morning, but student portal pe abhi bhi balance pending dikha raha hai. Registration hold lag jayega kya? Please check transaction and update ASAP. (Student ID: REQ-2026-000025, Course: EECS-280, Term: TERM-2026-FALL).', 'Time-Sensitive Academic Priority', 'resolved', 'Office of Financial Aid & Scholarships', 'RULE-FINAID-001', 'POL-FINAID-2026-006', '1.0', 'KB-000006', '2.0', FALSE, FALSE, NULL, 'Resolved in accordance with POL-FINAID-2026-006 v1.0 (Section 6.2) and KB-000006 v2.0.', TRUE, '2026-10-13T20:40:00+05:30', '2026-10-13T23:40:00+05:30', '2026-10-13T23:40:00+05:30', NULL)
