VALUES
  ('MSG-TKT-2026-000001-001', 'TKT-2026-000001', 1, 'REQ-2026-000001', NULL, 'learner', 'Elena Rostova', 'requester_inquiry', 'Fee paid hai online banking se yesterday morning, but student portal pe abhi bhi balance pending dikha raha hai. Registration hold lag jayega kya? Please check transaction and update ASAP. (Student ID: REQ-2026-000001, Course: CS-101, Term: TERM-2026-FALL).', NULL, NULL, NULL, NULL, '2026-10-09T22:06:00+05:30'),
  ('MSG-TKT-2026-000001-002', 'TKT-2026-000001', 2, 'SYSTEM-ROUTER', NULL, 'support_staff', 'CampusResolve Routing Engine', 'system_routing_note', 'Ticket TKT-2026-000001 classified under ''Financial Aid'' and assigned to ''Office of Financial Aid & Scholarships'' using routing rule RULE-FINAID-001.', NULL, NULL, NULL, NULL, '2026-10-09T22:31:00+05:30'),
  ('MSG-TKT-2026-000001-003', 'TKT-2026-000001', 3, 'ACTOR-OPS-FINAID', NULL, 'support_staff', 'Office of Financial Aid & Scholarships Specialist', 'ai_grounded_reply', 'Policy Guidance (POL-FINAID-2026-002 v2.0, KB-000002 v2.0): [SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Current SAP appeal requirements, 15-business-day submission window, and committee escalation rules.', 'POL-FINAID-2026-002', '2.0', 'KB-000002', '2.0', '2026-10-09T22:56:00+05:30'),
